    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Target graph and resultMap cannot be null");
    }

    Set<V> firstPartition = new HashSet<>();
    Set<V> secondPartition = new HashSet<>(resultMap.values());

    // Split the vertices into two partitions
    int partitionSize = secondPartition.size() / 2;
    int count = 0;
    for (V vertex : secondPartition) {
        if (count < partitionSize) {
            firstPartition.add(vertex);
        } else {
            secondPartition.add(vertex);
        }
        count++;
    }

    // Remove duplicates that might have been added to both partitions
    secondPartition.removeAll(firstPartition);

    // Add edges between all vertices in the two partitions
    for (V vertex1 : firstPartition) {
        for (V vertex2 : secondPartition) {
            if (!target.containsEdge(vertex1, vertex2)) {
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}

