int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    try {
        int size = schema.getSerializedSize(message);
        if (size >= 0x80000000) {
            throw new IOException("Serialized size exceeds max limit of 2^31-1");
        }
        writeVarint32(out, size);
        final int previousOffset = buffer.offset;
        final int startOffset = buffer.startOffset;
        final int limit = buffer.offset + size + 5; // 5 is avarint reserve size
        if (limit > buffer.buffer.length) {
            if (size > buffer.buffer.length) {
                // Expand the buffer to the exact length we need to serialize the message
                buffer = WrapperBuffer.wrap(new byte[size + previousOffset]);
            } else {
                // Resize the buffer to increase its capacity to fit the message plus the varint prefix
                buffer = new LinkedBuffer(buffer.buffer.length * 2 + 5, buffer);
            }
        }
        try {
            buffer.startOffset = buffer.offset;
            schema.writeTo(buffer, message);
        } finally {
            buffer.startOffset = startOffset;
        }
        int written = buffer.offset - previousOffset;
        if (written != size) {
            throw new IOException("Protocol message writer wrote " + written + " bytes, but indicated " + size + " bytes written to wire.  Something went wrong!");
        }
        out.write(buffer.buffer, previousOffset, written);
        return size;
    } finally {
        buffer.offset = buffer.startOffset;
    }
}

private static void writeVarint32(OutputStream out, int value) throws IOException {
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
}

int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments out, message, schema, and buffer cannot be null");
    }

    final byte[] delimBuffer = new byte[5];
    int size = 0;
    try {
        size = schema.getSerializedSize(message);
        int delimSize = CodedOutputStream.computeRawVarint32Size(size);
        CodedOutputStream codedOut = CodedOutputStream.newInstance(delimBuffer, 0, delimSize);
        codedOut.writeRawVarint32(size);
        codedOut.flush();

        out.write(delimBuffer, 0, delimSize);
        schema.writeTo(out, message, buffer);
    } finally {
        buffer.clear();
    }

    return size;
}

int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message, buffer);
    ProtobufOutput output = new ProtobufLinkedBufferOutput(buffer);
    output.writeRawVarint32(data.length);
    out.write(output.buffer, 0, output.size());
    out.write(data);
    return data.length;
}

