    // Assuming the year and month are correctly formatted, we focus on adjusting the day
    int dayOfWeek = getDayOfWeek(year, month, day);
    int adjustedDay = day - (dayOfWeek - 1) % dayStep;

    // Ensure the adjusted day is not less than 1
