private static String substituteVariables(String value, Properties props) {
    StringBuilder result = new StringBuilder();
    int varStart = 0;
    while (varStart >= 0) {
        varStart = value.indexOf("${", varStart);
        if (varStart < 0) {
            result.append(value.substring(varStart + 1));
            break;
        }
        int varEnd = value.indexOf("}", varStart);
        if (varEnd < 0) {
            result.append(value.substring(varStart));
            break;
        }
        result.append(value.substring(varStart + 1, varEnd));
        String varName = value.substring(varStart + 2, varEnd);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            result.append(varValue);
        }
        varStart = varEnd + 1;
    }
    return result.toString();
}

