List<PathSegmentImpl> function ( URI u , boolean decode ) { 
    List<PathSegmentImpl> pathSegments = new ArrayList<>(); 
    String path = u.getPath(); 
    if (path == null || path.isEmpty()) { 
        return pathSegments; 
    } 
    // If the path is absolute, skip the leading '/'
    int start = path.startsWith("/") ? 1 : 0; 
    for (int end = start; end < path.length(); end++) { 
        if (path.charAt(end) == '/') { 
            if (end > start) { 
                String segment = path.substring(start, end); 
                pathSegments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment, StandardCharsets.UTF_8) : segment)); 
            } 
            start = end + 1; 
        } 
    } 
    // Add the last segment
    if (start < path.length()) { 
        String segment = path.substring(start); 
        pathSegments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment, StandardCharsets.UTF_8) : segment)); 
    } 
    return pathSegments; 
}

