    }

    boolean isMethodDescriptor = descriptor.charAt(0) == '(';
    int index = isMethodDescriptor ? 1 : 0; // Start at 1 if it's a method descriptor to skip '('

    while (index < descriptor.length()) {
        char c = descriptor.charAt(index);
        switch (c) {
