                index++;
                popDoubleType();
                break;
            case '[': // Array
                while (descriptor.charAt(index) == '[') {
                    index++;
                }
                // After dimensions, there must be a type
                index++; // Move to the type character
                popSingleType();
                break;
            case 'L': // Object
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                index++; // Move past the ';'
                popSingleType();
                break;
            default:
                throw new IllegalArgumentException("Unexpected character in descriptor: " + c);
        }

        if (isMethodDescriptor && c == ')') {
            // End of method argument list
            break;
        }
    }
}

