private int popType(char[] chars, int i) {
    switch (chars[i]) {
        case 'B': // byte
        case 'C': // char
        case 'I': // int
        case 'S': // short
        case 'Z': // boolean
            // Each of these types occupies one slot in the operand stack
            return i + 1;
        case 'D': // double
        case 'J': // long
            // Each of these types occupies two slots in the operand stack
            return i + 1;
        case '[': // array
            // Skip the '[' characters
            while (chars[i] == '[') {
                i++;
            }
