void pop(final String descriptor) {
    try {
        if (descriptor == null) {
            throw new IllegalArgumentException("Descriptor cannot be null");
        }
        if (descriptor.startsWith("(")) {
            // This is a method descriptor, so extract the argument types part
            int endParenIndex = descriptor.indexOf(')');
            if (endParenIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
            }
            String argumentTypes = descriptor.substring(1, endParenIndex);
            int argsIndex = 0;
            while (argsIndex < argumentTypes.length()) {
                char typeChar = argumentTypes.charAt(argsIndex);
                switch (typeChar) {
                    case 'B':
                    case 'C':
                    case 'D':
                    case 'F':
                    case 'I':
                    case 'S':
                    case 'Z':
                        argsIndex += 1;
                        break;
                    case 'J':
                        argsIndex += 1;
                        break;
                    case 'L':
                        int semicolonIndex = argumentTypes.indexOf(';', argsIndex);
                        if (semicolonIndex == -1) {
                            throw new IllegalArgumentException("Invalid object descriptor: " + descriptor);
                        }
                        argsIndex = semicolonIndex + 1;
                        break;
                    case '[':
                        argsIndex += 1;
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character found in descriptor: " + typeChar);
                }
            }
        } else {
            // This is a field descriptor, so pop based on the type
            switch (descriptor.charAt(0)) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                case 'J':
                    break;
                case 'L':
                    if (descriptor.indexOf(';') == -1) {
                        throw new IllegalArgumentException("Invalid object descriptor: " + descriptor);
                    }
                    break;
                case '[':
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor type: " + descriptor);
            }
        }
    } catch (Exception e) {
        // Handle exception as appropriate, e.g., logging or throwing a new runtime exception
        throw new RuntimeException("Error popping from output frame stack: " + e.getMessage(), e);
    }
}

void pop(final String descriptor) {
    try {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }

        if (descriptor.charAt(0) == '(') { // Method descriptor
            int index = 1;
            while (descriptor.charAt(index) != ')') {
                index = popType(descriptor, index);
            }
        } else { // Type descriptor
            popType(descriptor, 0);
        }
    } catch (Exception e) {
        // Handle potential exceptions, e.g., malformed descriptor
        e.printStackTrace();
    }
}

private int popType(final String descriptor, int index) {
    char c = descriptor.charAt(index);
    if (c == 'B' || c == 'C' || c == 'D' || c == 'F' || c == 'I' || c == 'J' || c == 'S' || c == 'Z') {
        // Pop one slot for base types
        index++;
    } else if (c == 'L') {
        // Object type, pop one slot
        index = descriptor.indexOf(';', index) + 1;
    } else if (c == '[') {
        // Array type, pop one slot
        while (descriptor.charAt(index) == '[') {
            index++;
        }
        index = popType(descriptor, index); // Recurse for the array's element type
    }
    return index;
}

