public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder out = new StringBuilder();
    int i = 0;
    int len = str.length();
    while (i < len) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Invalid escape sequence");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    out.append('\b');
                    break;
                case 'f':
                    out.append('\f');
                    break;
                case 'n':
                    out.append('\n');
                    break;
                case 'r':
                    out.append('\r');
                    break;
                case 't':
                    out.append('\t');
                    break;
                case '\\':
                case '\'':
                case '\"':
                    out.append(next);
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    int value = 0;
                    for (int j = 1; j <= 4; j++) {
                        ch = str.charAt(++i);
                        switch (ch) {
                            case '0': case '1': case '2': case '3': case '4':
                            case '5': case '6': case '7': case '8': case '9':
                                value = (value << 4) + ch - '0';
                                break;
                            case 'a': case 'b': case 'c': case 'd': case 'e': case 'f':
                                value = (value << 4) + 10 + ch - 'a';
                                break;
                            case 'A': case 'B': case 'C': case 'D': case 'E': case 'F':
                                value = (value << 4) + 10 + ch - 'A';
                                break;
                            default:
                                throw new Exception("Invalid unicode escape sequence");
                        }
                    }
                    out.append((char) value);
                    break;
                default:
                    throw new Exception("Invalid escape sequence");
            }
            i++;
        } else {
            out.append(ch);
        }
        i++;
    }
    return out.toString();
}

