GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new SimpleGraphPath<>(graph);
    }

    GraphWalk<V, E> graphWalk = new DefaultGraphWalk<>(graph);
    List<E> edgeList = new ArrayList<>(tour);

    // Assuming the graph is connected and the tour forms a valid path
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    graphWalk.setStartVertex(startVertex);

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        // Ensure the path is valid
        if (!graphWalk.getVertexList().contains(source) || graphWalk.getEndVertex().equals(source)) {
            graphWalk.addEdge(edge);
            graphWalk.setEndVertex(target);
        } else {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }
    }

    return graphWalk;
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0.0);
    }
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexPath = new ArrayList<>();
    vertexPath.add(startVertex);
    double weight = 0.0;
    V currentVertex = startVertex;
    for (E edge : edgeList) {
        if (!graph.getEdgeSource(edge).equals(currentVertex) && !graph.getEdgeTarget(edge).equals(currentVertex)) {
            throw new IllegalArgumentException("Invalid tour: Edge does not connect to current path");
        }
        currentVertex = graph.getEdgeSource(edge).equals(currentVertex) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
        vertexPath.add(currentVertex);
        weight += graph.getEdgeWeight(edge);
    }
    return new GraphPathImpl<>(graph, startVertex, vertexPath, weight);
}

