GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<Edge<V, E>> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new SimpleGraphPath<>(graph, Collections.emptyList(), null, null, 0);
    }

    Map<V, List<E>> adjacencyList = new HashMap<>();
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        adjacencyList.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    Deque<E> pathEdges = new ArrayDeque<>();
    Deque<V> visitedVertices = new ArrayDeque<>();
    visitedVertices.push(startVertex);

    while (!adjacencyList.isEmpty()) {
        V currentVertex = visitedVertices.peek();
        List<E> edges = adjacencyList.get(currentVertex);
        if (edges == null || edges.isEmpty()) {
            visitedVertices.pop();
        } else {
            E nextEdge = edges.remove(0);
            if (edges.isEmpty()) {
                adjacencyList.remove(currentVertex);
            }
            V nextVertex = Graphs.getOppositeVertex(graph, nextEdge, currentVertex);
            pathEdges.push(nextEdge);
            visitedVertices.push(nextVertex);
        }
    }

    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);
    for (E edge : pathEdges) {
        V targetVertex = Graphs.getOppositeVertex(graph, edge, pathVertices.get(pathVertices.size() - 1));
        pathVertices.add(targetVertex);
    }

    return new SimpleGraphPath<>(graph, pathVertices, pathEdges, startVertex, pathVertices.get(pathVertices.size() - 1), pathEdges.size());
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new GraphWalk<>(graph, null, null, Collections.emptyList(), 0.0);
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertexList.add(targetVertex);
    }

    return new GraphWalk<>(graph, startVertex, vertexList.get(vertexList.size() - 1), vertexList, edgeList, 0.0);
}

