    if (graph == null || vertices == null || vertices.size() < 2) {
        return true; // A single vertex or null inputs are trivially a clique
    }

    try {
        for (V vertex1 : vertices) {
            for (V vertex2 : vertices) {
                if (!vertex1.equals(vertex2) && !graph.containsEdge(vertex1, vertex2)) {
                    return false; // If any two vertices are not connected, it's not a clique
                }
            }
        }
        return true; // All pairs of vertices are connected
    } catch (Exception e) {
        // Handle unexpected exceptions that might occur during graph operations
        return false;
    }
}

