void pop(final String descriptor) {
    char[] desc = descriptor.toCharArray();
    int index = 0;
    if (desc[0] == '(') {
        // It's a method descriptor, parse the argument types
        while (desc[index] != ')') {
            index = consumeType(desc, index);
        }
    } else {
        // It's a field descriptor, pop the type it describes
        consumeType(desc, index);
    }
}

private int consumeType(char[] desc, int index) {
    switch (desc[index]) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
            // Base types (byte, char, float, int, short, boolean) take up 1 slot
            return index + 1;
        case 'D': case 'J':
            // double and long take up 2 slots
            return index + 1;
        case 'L':
            // Object types (reference types) take up 1 slot
            while (desc[index] != ';') {
                index++;
            }
            return index + 1;
        case '[':
            // Arrays are treated as reference types and take up 1 slot
            return consumeType(desc, index + 1);
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + new String(desc));
    }
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    int i = 0;
    int charAt = descriptor.charAt(i);

    while (charAt != ')') {
        if (charAt == 'D' || charAt == 'J') {
            // double and long types take up two slots
            pop();
            pop();
        } else if (charAt != 'V') {
            // other object types and single-slot primitives take up one slot
            pop();
        }

        if (charAt == ')') {
            // move past the result type part of the method descriptor
            i++;
            break;
        }

        i++;
        if (charAt == '[') {
            // skip the array dimensions
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            // skip the element type
            charAt = descriptor.charAt(i);
            if (charAt == 'L') {
                // skip the object type name
                i = descriptor.indexOf(';', i) + 1;
                charAt = descriptor.charAt(i);
            }
        } else if (charAt == 'L') {
            // skip the object type name
            i = descriptor.indexOf(';', i) + 1;
            charAt = descriptor.charAt(i);
        } else {
            charAt = descriptor.charAt(i);
        }
    }
}

